int main() {
    Solution sol;

    vector<vector<int>> matrix1 = {{0, 1, 1, 1}, {1, 1, 1, 1}, {0, 1, 1, 1}};
    cout << "Example 1: " << sol.countSquares(matrix1) << " (expected 15)\n";

    vector<vector<int>> matrix2 = {{1, 0, 1}, {1, 1, 0}, {1, 1, 0}};
    cout << "Example 2: " << sol.countSquares(matrix2) << " (expected 7)\n";

    return 0;
}

